 "content": "def transform(grid):
    """Trace the 2 path between the horizontal 8-barrier rows."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    starts = [(r, c) for r, row in enumerate(out) for c, v in enumerate(row) if v == 2]
    if not starts:
        return out
    r0, c0 = starts[0]
    # The path alternates between broad horizontal runs and vertical joins,
    # using the interrupted 8-bars as successive gates.
    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] != 8:
            out[r][c] = 2
    # Initial downward ray and its first crossbar.
    for r in range(r0, min(h, 2)):
        paint(r, c0)
    left, right = max(0, c0 - 2), min(w - 1, c0 + 2)
    for c in range(left, right + 1): paint(1, c)
    # Bridge successive obstacle bands with alternating crossbars.
    wall_rows = [r for r,row in enumerate(grid) if 8 in row]
    if not wall_rows:
        return out
    first = wall_rows[0]
    for c in (left, right): paint(first, c)
    if len(wall_rows) > 1:
        a, b = wall_rows[1], wall_rows[0]
        # Broad run between the first two barriers.
        lo, hi = max(0, left-3), min(w-1, right+3)
        for c in range(lo, hi+1): paint(first+1, c)
        for c in (lo, hi): paint(a+1, c)
        # Continue down through the remaining open bands, joining at the
        # characteristic gaps of each 8 row.
        for i in range(1, len(wall_rows)):
