 "content": "def transform(grid):
    """Trace the 2 path through successive broken 8-lines."""
    def horizontal(g):
        out = [row[:] for row in g]
        h, w = len(g), len(g[0])
        walls = [r for r, row in enumerate(g) if 8 in row]
        if not walls:
            return out
        marker = next(((r, c) for r in range(h) for c in range(w) if g[r][c] == 2), None)

        # A path travels through each opening. Between barriers, each opening
        # continues vertically, ending before the next barrier's joining bar.
        for i, r in enumerate(walls):
            gaps = [c for c, value in enumerate(g[r]) if value == 0]
            for c in gaps:
                out[r][c] = 2
            end = walls[i + 1] - 2 if i + 1 < len(walls) else h - 1
            for c in gaps:
                for rr in range(r + 1, end + 1):
                    if out[rr][c] != 8:
                        out[rr][c] = 2
            # The row immediately before the following barrier joins its gaps.
            if i + 1 < len(walls):
                nr = walls[i + 1]
                ngaps = [c for c, value in enumerate(g[nr]) if value == 0]
                if ngaps:
                    rr = nr - 1
                    lo, hi = (0, w - 1) if len(ngaps) == 1 else (min(ngaps), max(ngaps))
                    for c in range(lo, hi + 1):
                        if out[rr][c] != 8:
                            out[rr][c] = 2

        # The input marker's incoming ray is preserved and connected to the
        # first barrier's opening(s) by the joining row above it.
        if marker:
            mr, mc = marker
            for rr in range(mr + 1, walls[0]):
                if out[rr][mc] != 8:
                    out[rr][mc] = 2
        return out

    # Identify whether the repeated broken barriers are horizontal or vertical.
    h, w = len(grid), len(grid[0])
    row_lines = sum(8 in row for row in grid)
    col_lines = sum(any(grid[r][c] == 8 for r in range(h)) for c in range(w))
    if col_lines > row_lines:
        t = [list(row) for row in zip(*grid)]
        result = horizontal(t)
        return [list(row) for row in zip(*result)]
    return horizontal(grid)

