    holes = [[c for c, value in enumerate(grid[r]) if value == 0] for r in bars]
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker is None or not bars:
        return out

    # Seed ray and connector to first barrier's openings.
    mr, mc = marker
    first = bars[0]
    for r in range(mr, first):
        if out[r][mc] != 8:
            out[r][mc] = 2
    if first > 0 and holes[0]:
        lo, hi = min([mc] + holes[0]), max([mc] + holes[0])
        for c in range(lo, hi + 1):
            if out[first - 1][c] != 8:
                out[first - 1][c] = 2

    for i, r in enumerate(bars):
        current = holes[i]
        for c in current:
            out[r][c] = 2
        if i + 1 < len(bars):
            nr = bars[i + 1]
            nxt = holes[i + 1]
            join = nr - 1
            # Current apertures form vertical rails; the next barrier's
            # approach row joins the current and next aperture spans. A lone
            # next opening creates a full-width crossbar.
            for c in current:
                for rr in range(r + 1, join):
                    if out[rr][c] != 8:
                        out[rr][c] = 2
            if nxt:
                if len(nxt) == 1:
                    lo, hi = 0, w - 1
                else:
                    points = current + nxt
                    lo, hi = min(points), max(points)
                for c in range(lo, hi + 1):
                    if out[join][c] != 8:
                        out[join][c] = 2
        else:
            for c in current:
                for rr in range(r + 1, h):
                    if out[rr][c] != 8:
