    """Extend a marker path through the openings in repeated barrier lines."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = [r for r, row in enumerate(grid) if 8 in row]
    if not bars:
        return out
    openings = [[c for c, value in enumerate(grid[r]) if value == 0] for r in bars]
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker:
        mr, mc = marker
        # Straight segment from the marker to the first obstacle.
        for rr in range(mr, bars[0]):
            if out[rr][mc] != 8:
                out[rr][mc] = 2

    # The crossing row immediately above each barrier joins its opening span.
    for i, r in enumerate(bars):
        gaps = openings[i]
        for c in gaps:
            out[r][c] = 2
        if r > 0 and gaps:
            lo, hi = min(gaps), max(gaps)
            for c in range(lo, hi + 1):
                if out[r - 1][c] != 8:
                    out[r - 1][c] = 2

        if i + 1 < len(bars):
            nr = bars[i + 1]
            nxt = openings[i + 1]
            # Each opening's rail continues down through the intervening area.
            for c in gaps:
                for rr in range(r + 1, nr):
                    if out[rr][c] != 8:
                        out[rr][c] = 2
            # If the next barrier has one opening, its approach row is a
            # complete horizontal crossbar. With multiple, it spans gaps.
            if nxt:
